<?php require_once '../config/auth.php'; exigirPerfil(['Administrador','Técnico','Trabalhador']); require_once '../config/conexao.php';$id=(int)($_GET['id']??0);if(!$id){header('Location: ../atendimentos.php?bloqueado=1');exit;}$d=['equipamento_id'=>'','descricao_problema'=>'','diagnostico'=>'','servico_realizado'=>'','status'=>'Aberta','valor'=>'','data_conclusao'=>''];$erro='';if($id){$st=$conn->prepare('SELECT * FROM ordens_servico WHERE id=?');$st->bind_param('i',$id);$st->execute();$x=$st->get_result()->fetch_assoc();if(!$x)exit('Ordem não encontrada.');$d=array_merge($d,$x);}$equip=$conn->query('SELECT e.id,e.tipo,e.marca,e.modelo,c.nome cliente FROM equipamentos e JOIN clientes c ON c.id=e.cliente_id ORDER BY c.nome');if($_SERVER['REQUEST_METHOD']==='POST'){$d=array_merge($d,$_POST);$eq=(int)($_POST['equipamento_id']??0);$prob=trim($_POST['descricao_problema']??'');$diag=trim($_POST['diagnostico']??'');$serv=trim($_POST['servico_realizado']??'');$status=$_POST['status']??'Aberta';$valor=($_POST['valor']??'')!==''?(float)str_replace(',','.',$_POST['valor']):null;$conclusao=$_POST['data_conclusao']?:null;if(!$eq||!$prob)$erro='Selecione o equipamento e descreva o problema relatado.';else{if($id){$st=$conn->prepare('UPDATE ordens_servico SET equipamento_id=?,descricao_problema=?,diagnostico=?,servico_realizado=?,status=?,valor=?,data_conclusao=? WHERE id=?');$st->bind_param('issssdsi',$eq,$prob,$diag,$serv,$status,$valor,$conclusao,$id);}else{$st=$conn->prepare('INSERT INTO ordens_servico(equipamento_id,descricao_problema,diagnostico,servico_realizado,status,valor,data_conclusao,data_abertura) VALUES(?,?,?,?,?,?,?,NOW())');$st->bind_param('issssds',$eq,$prob,$diag,$serv,$status,$valor,$conclusao);}if($st->execute()){header('Location: listar.php');exit;}else $erro='Não foi possível salvar a ordem de serviço. Confira os campos e a estrutura do banco.';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ordem de serviço | HelpTech</title><link rel="stylesheet" href="../css/style.css"></head><body><header class="topbar"><a class="brand" href="../dashboard.php"><span class="brand-mark">H</span>HelpTech</a><nav class="top-actions"><a href="../logout.php">Sair ↗</a></nav></header><main class="container form-container"><div class="eyebrow">Atendimento / Ordem de serviço</div><h1><?= 'Editar ordem #'.$id ?></h1><p class="subtitle">Registre o problema e acompanhe a evolução do reparo.</p><section class="form-card"><?php if($erro):?><div class="alert error"><?= h($erro) ?></div><?php endif;?><?php if(!$equip||$equip->num_rows===0):?><div class="alert error">Cadastre um cliente e um equipamento antes de abrir uma ordem.</div><a class="button" href="../equipamentos/cadastrar.php">Cadastrar equipamento</a><?php else:?><form method="post"><div class="form-grid"><div class="field full"><label>Equipamento / cliente *</label><select name="equipamento_id" required><option value="">Selecione o equipamento</option><?php while($e=$equip->fetch_assoc()):?><option value="<?= (int)$e['id'] ?>" <?= (int)$d['equipamento_id']===(int)$e['id']?'selected':'' ?>><?= h($e['cliente'].' — '.$e['tipo'].' '.$e['marca'].' '.$e['modelo']) ?></option><?php endwhile;?></select></div><div class="field full"><label>Problema relatado *</label><textarea name="descricao_problema" required><?= h($d['descricao_problema']) ?></textarea></div><div class="field full"><label>Diagnóstico técnico</label><textarea name="diagnostico"><?= h($d['diagnostico']) ?></textarea></div><div class="field full"><label>Serviço realizado</label><textarea name="servico_realizado"><?= h($d['servico_realizado']) ?></textarea></div><div class="field"><label>Status</label><select name="status"><?php foreach(['Aberta','Em andamento','Aguardando peça','Concluída','Entregue','Cancelada'] as $s):?><option <?= $d['status']===$s?'selected':'' ?>><?= h($s) ?></option><?php endforeach;?></select></div><div class="field"><label>Valor (R$)</label><input type="number" name="valor" min="0" step="0.01" value="<?= h($d['valor']) ?>"></div><div class="field"><label>Data de conclusão</label><input type="date" name="data_conclusao" value="<?= h($d['data_conclusao']?substr($d['data_conclusao'],0,10):'') ?>"></div></div><div class="form-actions"><button>Salvar ordem de serviço</button><a class="button secondary" href="listar.php">Cancelar</a></div></form><?php endif;?></section></main></body></html>